; } break; } return $allow; } public function is_low_originality($item) { return !apply_filters('qqworld-collector-pseudo-original-is-low-originality', false, $item ); } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $allowed = isset($args['allowed']) ? $args['allowed'] : ''; $disallowed = isset($args['disallowed']) ? $args['disallowed'] : ''; $empty = isset($args['empty']) ? $args['empty'] : 0; $duplicated = isset($args['duplicated']) ? $args['duplicated'] : 0; $low_originality = isset($args['low_originality']) ? $args['low_originality'] : 0; $less = isset($args['less']) ? $args['less'] : ''; $more = isset($args['more']) ? $args['more'] : ''; $number_less = isset($args['number_less']) ? $args['number_less'] : ''; $number_more = isset($args['number_more']) ? $args['number_more'] : ''; $allow = $empty ? !empty($item) : true; if ($allow && $allowed) $allow = $this->is_allowed($item, $allowed); if ($allow && $disallowed) $allow = $this->is_disallowd($item, $disallowed); if ($allow && $item && $duplicated) $allow = $this->is_duplicated($item, $type, $item_args); if ($allow && $item && $low_originality) $allow = $this->is_low_originality($item); if ($allow && $item && $less) $allow = mb_strlen($item) >= $less; if ($allow && $item && $more) $allow = mb_strlen($item) <= $more; if ($allow && $item && $number_less) $allow = floatval($item) >= $number_less; if ($allow && $item && $number_more) $allow = floatval($item) <= $number_more; if (!$allow) $item .= '(disallowed:'.__('Excluded by Ignore by Keyword filter', $this->text_domain).')'; return $item; } public function parse($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (is_string($item)) { if ( !preg_match('/\(disallowed:[^\)]*\)/i', $item) ) $item = $this->filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode); } else { if (empty($item)) { $item[] = $this->filter('', $args, $source_link, $html, $type, $item_args, $download_args, $mode); } else { foreach ($item as &$i) { if ( !preg_match('/\(disallowed:[^\)]*\)/i', $i) ) $i = $this->filter($i, $args, $source_link, $html, $type, $item_args, $download_args, $mode); } } } return $item; } } ?>